package reactions

// The palette: the closed set of reactions, and the only moderation policy
// this package has.
//
// It is closed on purpose. A free-text reaction is a comment, a comment needs
// moderation, and moderation is the thing worth not building. Six is enough to
// say something and few enough to fit on one line on a phone.
//
// Every glyph here is a SINGLE codepoint with no variation selector (no
// U+FE0F) and no zero-width joiner. That is a constraint, not a coincidence:
// these strings pass through a markdown escaper that strips zero-width and
// bidi characters, and a glyph that needs U+FE0F to render would come out the
// other side as its bare monochrome form. ❤️ is the obvious casualty, which is
// why "heart" is 💜 (U+1F49C), a codepoint that is a colour emoji on its own.
const (
	// KeyUp is the default, first in the strip.
	KeyUp = "up"
	// KeyHeart is affection rather than agreement.
	KeyHeart = "heart"
	// KeyFire is "this is good".
	KeyFire = "fire"
	// KeyParty is a congratulation.
	KeyParty = "party"
	// KeyRocket is "ship it".
	KeyRocket = "rocket"
	// KeyEyes is "I am watching this", the only one that is not praise.
	KeyEyes = "eyes"
)

// order is the display order of the palette, which is also the order the
// strip renders in. A slice and not a map range: gno map iteration order is
// unspecified, and a Render that reshuffles between identical calls is a
// consensus bug.
var order = []string{KeyUp, KeyHeart, KeyFire, KeyParty, KeyRocket, KeyEyes}

// palette maps a key to its glyph. Written as \U escapes rather than literal
// emoji so that the source says exactly which codepoint it means and a review
// diff cannot hide a lookalike.
var palette = map[string]string{
	KeyUp:     "\U0001F44D", // 👍
	KeyHeart:  "\U0001F49C", // 💜
	KeyFire:   "\U0001F525", // 🔥
	KeyParty:  "\U0001F389", // 🎉
	KeyRocket: "\U0001F680", // 🚀
	KeyEyes:   "\U0001F440", // 👀
}

// Keys returns the palette keys in display order. The returned slice is a copy,
// so a caller cannot reorder the palette for everyone else.
func Keys() []string {
	out := make([]string, len(order))
	copy(out, order)
	return out
}

// Valid reports whether key names a reaction in the palette.
func Valid(key string) bool {
	_, ok := palette[key]
	return ok
}

// Emoji returns the glyph for a palette key, or "" when the key is not one.
func Emoji(key string) string { return palette[key] }

// Package reactions is the engine behind an embeddable reaction block: the
// one-click "👍 3 · 🔥 1" strip a realm drops into its own Render, keyed on
// the PAGE it is showing rather than on the realm that stores it.
//
// That indirection is the whole idea, and it is the one the web already
// settled on: a single hosted widget, embedded verbatim everywhere, deciding
// what to show from the page identifier it is handed. One realm holds every
// tally, every host realm ships the same two lines, and no host realm stores
// anything.
//
// # The model
//
// A [Board] maps a page key to a [Page]. A page holds three things and
// deliberately nothing else:
//
//   - a count per palette key,
//   - the CURRENT reaction of each address, so a tally counts addresses and
//     not clicks, and so a reader can change their mind,
//   - the last reaction: which key, from whom, at what height.
//
// There is no text anywhere, which is the point. Text needs moderation;
// a closed palette of six emoji does not.
//
// # Keys are names, not glyphs
//
// A reaction is stored and addressed as an ASCII name ("up", "fire"), and the
// glyph is presentation. A name survives a URL query parameter, an avl key and
// a markdown escaper without a single encoding question, and the palette can
// gain a glyph without rewriting stored state.
//
// # Page keys
//
// A page key is a package path (the full one, chain domain included, as
// unsafe.CurrentRealm().PkgPath() reports it). [ValidPage] is what bounds this
// package's exposure: a key is path-shaped, ASCII, and at most [MaxPageLen]
// bytes, so a stored key can never be a markdown payload, a bidi run or an
// unbounded blob. This package only ever puts it in a URL; a realm that shows
// the key as text escapes it there, because a validator and an escaper protect
// against different mistakes.
package reactions

import (
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/nt/avl/v0"
)

// MaxPageLen is the longest page key accepted. Comfortably past the longest
// real package path (the deepest in moul/gno-contracts is 34 bytes) and short
// enough that a key can never be a payload.
const MaxPageLen = 120

// Board is a set of pages, each with its own tally. The zero value is not
// usable; call [NewBoard].
type Board struct {
	pages *avl.Tree // page key -> *Page
}

// NewBoard returns an empty board.
func NewBoard() *Board { return &Board{pages: avl.NewTree()} }

// Page is one page's tally.
//
// Every read method is nil-safe and answers as if the page were empty, so a
// caller can hand [Board.Page]'s result straight to [Block] without checking.
type Page struct {
	counts  *avl.Tree // palette key -> int
	by      *avl.Tree // address string -> palette key
	lastKey string
	lastWho address
	lastAt  int64
}

// React records who's reaction on page, replacing whatever they had there
// before. It reports whether anything was stored: false means the page key or
// the palette key was rejected, and nothing changed.
//
// height is passed in rather than read from the chain, so this package stays
// testable without a realm and so the caller decides what "when" means.
func (b *Board) React(page string, who address, key string, height int64) bool {
	if !ValidPage(page) || !Valid(key) {
		return false
	}
	p := b.page(page)

	// Replacing a reaction decrements the old bucket first. Without this a
	// reader who clicks twice counts twice, and the tally stops meaning
	// "how many addresses", which is the only thing it is allowed to mean.
	if prev := p.Of(who); prev != "" {
		if prev == key {
			// Same key again: still record it as the last reaction, since the
			// click happened, but leave the counts alone.
			p.lastKey, p.lastWho, p.lastAt = key, who, height
			return true
		}
		p.add(prev, -1)
	}
	p.by.Set(who.String(), key)
	p.add(key, 1)
	p.lastKey, p.lastWho, p.lastAt = key, who, height
	return true
}

// Unreact removes who's reaction from page. It reports whether there was one.
//
// The last-reaction line is deliberately NOT rewound: it records an event that
// happened, and recomputing it would mean walking every address on the page.
// [Page.Last] therefore keeps naming a reaction nobody holds any more, which is
// the honest answer to "what happened here last". What is shown is a separate
// decision, and [Summary] makes it: a page with no reactors left renders as
// empty, not as a withdrawn reaction.
func (b *Board) Unreact(page string, who address) bool {
	p := b.Page(page)
	if p == nil {
		return false
	}
	prev := p.Of(who)
	if prev == "" {
		return false
	}
	p.by.Remove(who.String())
	p.add(prev, -1)
	return true
}

// Page returns the tally for a page, or nil when nothing was ever recorded
// there. The nil is safe to use: every [Page] read method handles it.
func (b *Board) Page(page string) *Page {
	v := b.pages.Get(page)
	if v == nil {
		return nil
	}
	return v.(*Page)
}

// page returns the tally for a page, creating it if needed.
func (b *Board) page(key string) *Page {
	if p := b.Page(key); p != nil {
		return p
	}
	p := &Page{counts: avl.NewTree(), by: avl.NewTree()}
	b.pages.Set(key, p)
	return p
}

// Pages reports how many pages have ever been reacted to.
func (b *Board) Pages() int { return b.pages.Size() }

// Each visits every page in key order until fn returns true.
func (b *Board) Each(fn func(page string, p *Page) bool) {
	b.pages.Iterate("", "", func(key string, value any) bool {
		return fn(key, value.(*Page))
	})
}

// add changes a bucket by delta, dropping it when it reaches zero so an
// emptied page leaves no residue behind.
func (p *Page) add(key string, delta int) {
	n := p.Count(key) + delta
	if n <= 0 {
		p.counts.Remove(key)
		return
	}
	p.counts.Set(key, n)
}

// Count reports how many addresses currently hold this reaction.
func (p *Page) Count(key string) int {
	if p == nil {
		return 0
	}
	v := p.counts.Get(key)
	if v == nil {
		return 0
	}
	return v.(int)
}

// Total is the number of addresses reacting to this page. It equals the sum of
// every bucket, because an address holds at most one reaction.
func (p *Page) Total() int {
	if p == nil {
		return 0
	}
	return p.by.Size()
}

// Of returns who's current reaction key, or "" when they have none.
func (p *Page) Of(who address) string {
	if p == nil {
		return ""
	}
	v := p.by.Get(who.String())
	if v == nil {
		return ""
	}
	return v.(string)
}

// Last returns the most recent reaction: its palette key, who made it, and the
// height it was made at. The key is "" when the page has never been reacted to.
//
// It can name a reaction that is no longer counted, because [Board.Unreact]
// does not rewind it. That is the honest answer to "what happened here last",
// which is the question the line under the block asks.
func (p *Page) Last() (key string, who address, height int64) {
	if p == nil {
		return "", "", 0
	}
	return p.lastKey, p.lastWho, p.lastAt
}

// ValidPage reports whether page is an acceptable key.
//
// The rule is "a gnoweb render path, and nothing that is not one": at least one
// "/", no empty element, no leading or trailing "/", and only lowercase ASCII
// letters, digits, ".", "-", "_", ":" and "/". That excludes every character a
// markdown escaper exists for, plus every byte above ASCII, so a stored key
// cannot carry a bidi run, a zero-width joiner or an image.
//
// Two of the exclusions are STRUCTURAL and not about markdown, so widening this
// set is not free. gnoweb parses a render path as `<path>[:<args>][$<webargs>]`
// and cuts on "$" BEFORE it cuts on ":" (gno.land/pkg/gnoweb/weburl/url.go,
// ParseFromURL, read 2026-09-28), so a "$" in a key would truncate it on the
// way back in, and a "%" would be eaten by the unescape that follows. ":" is
// safe only because that second cut takes the FIRST colon, which leaves the
// rest of the key intact however many it carries.
//
// ":" is in the set because a host realm keying the block per article wants the
// path it already serves: "gno.land/r/you/blog:hello-world".
func ValidPage(page string) bool {
	if page == "" || len(page) > MaxPageLen {
		return false
	}
	if strings.HasPrefix(page, "/") || strings.HasSuffix(page, "/") ||
		strings.Contains(page, "//") || !strings.Contains(page, "/") {
		return false
	}
	for i := 0; i < len(page); i++ {
		c := page[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '/' || c == '.' || c == '-' || c == '_' || c == ':':
		default:
			return false
		}
	}
	return true
}

// Block renders the embeddable widget: the clickable palette with its counts,
// then one line saying what happened here last.
//
// realmPath is the realm that owns React, given as the full package path from
// its gnomod.toml module line. It is a parameter and not a constant because
// this package is the engine and not the deployment: a second reactions realm,
// on another chain or in a test, renders through the same code.
//
// page appears only in URL positions here: as a txlink query argument, which
// txlink percent-encodes, and inside [PageURL]. Nothing renders it as text, and
// [ValidPage]'s charset is what keeps the [PageURL] form safe. A realm showing
// the key itself must still run it through ui.Inline.
//
// The result ends with a single newline and contains exactly one blank line,
// so it drops into a host realm's Render between two sections without a
// separator of its own.
func Block(realmPath, page string, p *Page) string {
	var b strings.Builder
	for i, key := range order {
		if i > 0 {
			b.WriteString(" ")
		}
		title := palette[key]
		if n := p.Count(key); n > 0 {
			title += " " + strconv.Itoa(n)
		}
		b.WriteString(ui.ActionIn(realmPath, title, "React", "page", page, "key", key))
	}
	b.WriteString("\n\n")
	b.WriteString(md.Italic(Summary(realmPath, page, p)))
	b.WriteString("\n")
	return b.String()
}

// Summary is the one line under the block: the last reaction, and a link to
// the page's own view on the reactions realm. Plain markdown, no wrapper, so a
// caller can put it somewhere else.
func Summary(realmPath, page string, p *Page) string {
	key, who, _ := p.Last()
	n := p.Total()

	// Two different ways to have nothing to say, and both have to be checked.
	// key == "" is a page nobody ever touched. n == 0 is a page whose reactors
	// have all left: [Board.Unreact] deliberately does not rewind the last
	// reaction, so key still names one. Gating on key alone would print
	// "last <emoji> by <addr> - 0 reactions" above an empty strip, which
	// contradicts itself and keeps attributing a reaction its author took back.
	if key == "" || n == 0 {
		return "no reactions yet"
	}
	label := strconv.Itoa(n) + " reaction"
	if n != 1 {
		label += "s"
	}
	return "last " + palette[key] + " by " + ui.Addr(who) + " · " +
		md.Link(label, PageURL(realmPath, page))
}

// RealmURL is the gnoweb path of a realm given as a package path.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it. Derived here rather than read from chain/runtime so this
// package keeps no chain import of its own and the rule stays in one place.
// Returns "" for something that is not a package path.
func RealmURL(realmPath string) string {
	i := strings.Index(realmPath, "/")
	if i < 0 {
		return ""
	}
	return realmPath[i:]
}

// PageURL is the link to one page's view on the reactions realm: [RealmURL]
// with the page as the gnoweb render argument after a colon.
func PageURL(realmPath, page string) string {
	base := RealmURL(realmPath)
	if base == "" {
		return ""
	}
	return base + ":" + page
}

package reactions

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const (
	realmPath = "gno.land/r/test/reactions/v0"
	homePage  = "gno.land/r/moul/home"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
)

func TestValidPage(t *testing.T) {
	cases := []struct {
		page string
		want bool
	}{
		{"gno.land/r/moul/home", true},
		{"gno.land/p/moul/kit/ui/v0", true},
		{"gno.land/r/moul/x/daily/b58demo", true},
		{"a/b", true},
		{"gno.land/r/you/blog:hello-world", true}, // one page per article
		{"", false},
		{"nolslash", false},
		{"/leading", false},
		{"trailing/", false},
		{"double//slash", false},
		{"gno.land/r/MOUL/home", false},                   // uppercase is not a path here
		{"gno.land/r/moul/home ", false},                  // a space is not path-shaped
		{"gno.land/r/[x](http://e.vil)", false},           // a markdown link cannot be a key
		{"gno.land/r/‮moul/home", false},             // bidi override
		{strings.Repeat("a/", MaxPageLen) + "b", false},   // over the cap
		{strings.Repeat("a", MaxPageLen-2) + "/b", true},  // exactly at the cap
		{strings.Repeat("a", MaxPageLen-1) + "/b", false}, // one byte over
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidPage(tc.page), tc.page)
	}
}

func TestPaletteIsClosed(t *testing.T) {
	uassert.Equal(t, 6, len(Keys()))
	for _, k := range Keys() {
		uassert.True(t, Valid(k), k)
		uassert.NotEqual(t, "", Emoji(k), k)
	}
	uassert.False(t, Valid("poop"))
	uassert.Equal(t, "", Emoji("poop"))

	// Keys returns a copy: reordering it must not reorder the palette.
	ks := Keys()
	ks[0] = "clobbered"
	uassert.Equal(t, KeyUp, Keys()[0])
}

// TestNilPageReadsAsEmpty is what lets a host realm render the block without
// ever checking whether the page exists.
func TestNilPageReadsAsEmpty(t *testing.T) {
	var p *Page
	uassert.Equal(t, 0, p.Count(KeyUp))
	uassert.Equal(t, 0, p.Total())
	uassert.Equal(t, "", p.Of(alice))
	key, who, at := p.Last()
	uassert.Equal(t, "", key)
	uassert.Equal(t, address(""), who)
	uassert.Equal(t, int64(0), at)
}

func TestReactCountsAddressesNotClicks(t *testing.T) {
	b := NewBoard()

	uassert.True(t, b.React(homePage, alice, KeyUp, 100))
	uassert.True(t, b.React(homePage, alice, KeyUp, 101))
	uassert.True(t, b.React(homePage, alice, KeyUp, 102))

	p := b.Page(homePage)
	uassert.Equal(t, 1, p.Count(KeyUp), "three clicks from one address is one reaction")
	uassert.Equal(t, 1, p.Total())

	// The repeat still counts as the last event, because it happened.
	_, _, at := p.Last()
	uassert.Equal(t, int64(102), at)
}

func TestChangingReactionMovesTheCount(t *testing.T) {
	b := NewBoard()
	b.React(homePage, alice, KeyUp, 100)
	b.React(homePage, bob, KeyUp, 101)
	b.React(homePage, alice, KeyFire, 102)

	p := b.Page(homePage)
	uassert.Equal(t, 1, p.Count(KeyUp))
	uassert.Equal(t, 1, p.Count(KeyFire))
	uassert.Equal(t, 2, p.Total(), "changing a reaction never changes the head count")
	uassert.Equal(t, KeyFire, p.Of(alice))
	uassert.Equal(t, KeyUp, p.Of(bob))
}

func TestUnreact(t *testing.T) {
	b := NewBoard()
	b.React(homePage, alice, KeyUp, 100)

	uassert.False(t, b.Unreact("gno.land/r/never/touched", alice), "no page")
	uassert.False(t, b.Unreact(homePage, bob), "no reaction of bob's")
	uassert.True(t, b.Unreact(homePage, alice))
	uassert.False(t, b.Unreact(homePage, alice), "removing twice is not an error, just false")

	p := b.Page(homePage)
	uassert.Equal(t, 0, p.Count(KeyUp), "an emptied bucket leaves no residue")
	uassert.Equal(t, 0, p.Total())

	// Last is deliberately not rewound: it records what happened.
	key, who, _ := p.Last()
	uassert.Equal(t, KeyUp, key)
	uassert.Equal(t, alice, who)
}

func TestReactRejects(t *testing.T) {
	b := NewBoard()
	uassert.False(t, b.React("not a path", alice, KeyUp, 1), "bad page")
	uassert.False(t, b.React(homePage, alice, "poop", 1), "key outside the palette")
	uassert.Equal(t, 0, b.Pages(), "a rejected reaction creates no page")
}

func TestPagesAreIndependentAndOrdered(t *testing.T) {
	b := NewBoard()
	b.React("gno.land/r/moul/home", alice, KeyUp, 1)
	b.React("gno.land/r/moul/blog", bob, KeyFire, 2)
	b.React("gno.land/r/moul/blog", carol, KeyFire, 3)

	uassert.Equal(t, 2, b.Pages())
	uassert.Equal(t, 1, b.Page("gno.land/r/moul/home").Total())
	uassert.Equal(t, 2, b.Page("gno.land/r/moul/blog").Total())

	var seen []string
	b.Each(func(page string, p *Page) bool {
		seen = append(seen, page)
		return false
	})
	uassert.Equal(t, "gno.land/r/moul/blog,gno.land/r/moul/home", strings.Join(seen, ","),
		"Each walks in key order, so a Render built from it is stable")
}

func TestEachStopsOnTrue(t *testing.T) {
	b := NewBoard()
	b.React("gno.land/r/a/one", alice, KeyUp, 1)
	b.React("gno.land/r/b/two", alice, KeyUp, 2)

	n := 0
	b.Each(func(page string, p *Page) bool {
		n++
		return true
	})
	uassert.Equal(t, 1, n)
}

func TestRealmAndPageURL(t *testing.T) {
	uassert.Equal(t, "/r/test/reactions/v0", RealmURL(realmPath))
	uassert.Equal(t, "", RealmURL("nodomain"))
	uassert.Equal(t, "/r/test/reactions/v0:gno.land/r/moul/home",
		PageURL(realmPath, homePage))
	uassert.Equal(t, "", PageURL("nodomain", homePage))
}

// TestBlockShape pins the embed byte for byte. It is a Test and not an Example
// because the block contains a blank line, and gno collapses consecutive blank
// lines inside an // Output: block.
func TestBlockShape(t *testing.T) {
	b := NewBoard()

	empty := "[\U0001F44D](/r/test/reactions/v0$help&func=React&key=up&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F49C](/r/test/reactions/v0$help&func=React&key=heart&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F525](/r/test/reactions/v0$help&func=React&key=fire&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F389](/r/test/reactions/v0$help&func=React&key=party&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F680](/r/test/reactions/v0$help&func=React&key=rocket&page=gno.land%2Fr%2Fmoul%2Fhome) " +
		"[\U0001F440](/r/test/reactions/v0$help&func=React&key=eyes&page=gno.land%2Fr%2Fmoul%2Fhome)" +
		"\n\n*no reactions yet*\n"
	uassert.Equal(t, empty, Block(realmPath, homePage, b.Page(homePage)),
		"a page nobody has reacted to still renders the whole strip")

	b.React(homePage, alice, KeyUp, 100)
	b.React(homePage, bob, KeyUp, 101)
	b.React(homePage, carol, KeyFire, 102)

	got := Block(realmPath, homePage, b.Page(homePage))
	uassert.True(t, strings.Contains(got, "[\U0001F44D 2]"), "the count rides in the link title")
	uassert.True(t, strings.Contains(got, "[\U0001F525 1]"))
	uassert.True(t, strings.Contains(got, "[\U0001F389]"), "an empty bucket shows no zero")
	uassert.True(t, strings.Contains(got, "last \U0001F525 by "))
	uassert.True(t, strings.Contains(got, "[3 reactions](/r/test/reactions/v0:gno.land/r/moul/home)"))
	uassert.True(t, strings.HasSuffix(got, "*\n"), "one trailing newline, so it drops into a Render")
}

func TestSummaryPluralises(t *testing.T) {
	b := NewBoard()
	b.React(homePage, alice, KeyUp, 100)
	uassert.True(t, strings.Contains(Summary(realmPath, homePage, b.Page(homePage)), "[1 reaction]"))

	b.React(homePage, bob, KeyUp, 101)
	uassert.True(t, strings.Contains(Summary(realmPath, homePage, b.Page(homePage)), "[2 reactions]"))
}

// TestEmojiSurviveTheEscaper is the reason the palette holds no U+FE0F and no
// zero-width joiner: ui.ActionIn escapes the link title, and that escaper
// strips exactly those. A glyph that does not survive it renders as a
// monochrome box on every page that embeds the block.
func TestEmojiSurviveTheEscaper(t *testing.T) {
	b := NewBoard()
	for _, k := range Keys() {
		got := Block(realmPath, homePage, b.Page(homePage))
		uassert.True(t, strings.Contains(got, "["+Emoji(k)+"]"), k)
	}
}

// TestSummaryGoesEmptyWhenEveryoneLeaves is the interaction between the two
// halves of Last: it is deliberately not rewound by Unreact, so the summary has
// to decide for itself whether there is anything left to summarise. Gating on
// the last key alone would print "last 👍 by g1… · 0 reactions" above an empty
// strip, which contradicts itself and keeps attributing a reaction its author
// took back.
func TestSummaryGoesEmptyWhenEveryoneLeaves(t *testing.T) {
	b := NewBoard()
	b.React(homePage, alice, KeyUp, 100)
	b.Unreact(homePage, alice)

	p := b.Page(homePage)
	uassert.Equal(t, 0, p.Total(), "the tally is empty")

	key, _, _ := p.Last()
	uassert.Equal(t, KeyUp, key, "and Last still records the event, by design")

	uassert.Equal(t, "no reactions yet", Summary(realmPath, homePage, p),
		"so the summary shows the empty state rather than a withdrawn reaction")

	uassert.True(t, strings.HasSuffix(Block(realmPath, homePage, p), "*no reactions yet*\n"))
}

// Package reactions is a reaction block any realm can embed, keyed on the page
// it appears on rather than on the realm that stores it.
//
// It is the shape the web settled on for this in 2010: one hosted widget, the
// same snippet pasted everywhere, deciding what to show from the page
// identifier it is handed. Here the snippet is two lines of gno:
//
//	import "gno.land/r/moul/reactions/v0"
//
//	func Render(path string) string {
//		return body + reactions.RenderBlock()
//	}
//
// [RenderBlock] takes no argument because it does not need one: a plain read
// exported by a realm and called by another opens no realm frame, so
// unsafe.CurrentRealm() inside it reports the CALLER. The host realm's own path
// is the page key, and nothing has to be configured, registered or passed.
// [RenderBlockFor] is the explicit form, for a realm that renders more than one
// page or already holds its path as a constant.
//
// The host realm stores nothing. Every tally lives here, so a realm can add
// reactions without a redeploy the next time it wants to change them, and a
// reader's reaction survives the host realm being replaced.
//
// # What it is not
//
// Not a comment system. There is no text field anywhere, which is what makes
// it possible to run with no moderation at all: six emoji, one reaction per
// address per page, changeable and removable. The page shows the tally and who
// reacted last. That is the whole feature.
package reactions

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	rx "gno.land/p/moul/reactions/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from unsafe.CurrentRealm(),
// which reports the CALLER in every read this realm exports and would therefore
// build every link against whichever realm embedded the block.
const realmPath = "gno.land/r/moul/reactions/v0"

// board holds every page's tally.
//
// A redeploy would wipe it, which is why this realm is not private (see
// gnomod.toml): the state here belongs to everyone who reacted, and the only
// honest way to change this realm is a v1 beside it.
var board = rx.NewBoard()

// React records the caller's reaction to page.
//
// page is a package path, the full one: "gno.land/r/moul/home". It does not
// have to be a realm that embeds the block, and nothing checks that it exists.
// A page is just a name, which is what lets a realm key the block on something
// finer than itself.
//
// key is one of the palette names, not a glyph: "up", "heart", "fire", "party",
// "rocket", "eyes". Render("") lists them with their emoji.
//
// One reaction per address per page. Reacting again with a different key moves
// it; reacting with the same key changes nothing but the "last reaction" line.
func React(cur realm, page, key string) {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !rx.Valid(key) {
		panic("reactions: no such reaction: " + key)
	}
	if !rx.ValidPage(page) {
		panic("reactions: not a page key: " + page)
	}

	who := unsafe.PreviousRealm().Address()
	board.React(page, who, key, runtime.ChainHeight())
	chain.Emit("React", "page", page, "key", key, "who", who.String())
}

// Unreact removes the caller's reaction from page. It aborts when there is
// none, rather than succeeding silently, so a misspelled page key is visible
// instead of looking like a no-op.
func Unreact(cur realm, page string) {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	who := unsafe.PreviousRealm().Address()
	if !board.Unreact(page, who) {
		panic("reactions: nothing to remove on " + page)
	}
	chain.Emit("Unreact", "page", page, "who", who.String())
}

// RenderBlock returns the block for the realm CALLING it, which is the form a
// host realm embeds.
//
// It has no cur realm parameter on purpose. A plain read is borrowed: gno opens
// no realm frame for it, so unsafe.CurrentRealm() reports the caller's path and
// the block keys itself with no argument. Adding a cur realm here would
// silently reverse that and key every embed to this realm instead.
//
// Calling it from inside this realm therefore keys on this realm, which is
// never what a caller wants; the views below use the unexported blockFor.
func RenderBlock() string {
	return blockFor(unsafe.CurrentRealm().PkgPath())
}

// RenderBlockFor is [RenderBlock] for a named page. Use it from a crossing
// function, where there is no caller to read off the stack, or when one realm
// renders several pages.
func RenderBlockFor(page string) string { return blockFor(page) }

// blockFor is the shared body, so no exported read of this realm calls another
// and picks up the wrong path.
func blockFor(page string) string {
	return rx.Block(realmPath, page, board.Page(page))
}

// Count reports how many addresses have a reaction on page.
func Count(page string) int { return board.Page(page).Total() }

// CountOf reports how many addresses hold one particular reaction on page.
func CountOf(page, key string) int { return board.Page(page).Count(key) }

// ReactionOf returns who's current reaction key on page, or "" when they have
// none. A host realm can use it to say "you reacted" without reading the tree.
func ReactionOf(page string, who address) string { return board.Page(page).Of(who) }

// Last returns the most recent reaction on page: the palette key, the address,
// and the height. The key is "" when the page has never been reacted to.
func Last(page string) (key string, who address, height int64) {
	return board.Page(page).Last()
}

// Pages reports how many pages have ever been reacted to.
func Pages() int { return board.Pages() }

package reactions

import (
	"strconv"
	"strings"
	"testing"

	rx "gno.land/p/moul/reactions/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const homePage = "gno.land/r/moul/home"

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
)

// reset clears realm state. Realm globals live for the whole test binary, and
// the Example runs after every Test, so everything that renders starts here.
func reset() { board = rx.NewBoard() }

func TestReactAndUnreact(cur realm, t *testing.T) {
	reset()

	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyUp)
	testing.SetRealm(testing.NewUserRealm(bob))
	React(cross(cur), homePage, rx.KeyFire)

	uassert.Equal(t, 2, Count(homePage))
	uassert.Equal(t, 1, CountOf(homePage, rx.KeyUp))
	uassert.Equal(t, rx.KeyUp, ReactionOf(homePage, alice))
	uassert.Equal(t, 1, Pages())

	key, who, _ := Last(homePage)
	uassert.Equal(t, rx.KeyFire, key)
	uassert.Equal(t, bob, who)

	testing.SetRealm(testing.NewUserRealm(alice))
	Unreact(cross(cur), homePage)
	uassert.Equal(t, 1, Count(homePage))
	uassert.Equal(t, "", ReactionOf(homePage, alice))
}

func TestReadsOnAnUntouchedPageAreZero(t *testing.T) {
	reset()
	uassert.Equal(t, 0, Count("gno.land/r/nobody/here"))
	uassert.Equal(t, 0, CountOf("gno.land/r/nobody/here", rx.KeyUp))
	uassert.Equal(t, "", ReactionOf("gno.land/r/nobody/here", alice))
	key, _, _ := Last("gno.land/r/nobody/here")
	uassert.Equal(t, "", key)
}

func TestReactRefusals(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: no such reaction: poop", func() {
		React(cross(cur), homePage, "poop")
	})

	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: not a page key: not a path", func() {
		React(cross(cur), "not a path", rx.KeyUp)
	})

	uassert.Equal(t, 0, Pages(), "a refused reaction creates no page")
}

// TestUnreactAbortsRatherThanNoOp is the deliberate asymmetry: a misspelled
// page key on Unreact has to be visible, or a reader thinks they removed
// something they did not.
func TestUnreactAbortsRatherThanNoOp(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "reactions: nothing to remove on "+homePage, func() {
		Unreact(cross(cur), homePage)
	})
}

// TestRenderBlockForIsWhatTheBlockLinksTo pins the property a host realm
// depends on: every link in the embedded block points at THIS realm, not at
// the realm that embedded it, and carries the page key as an argument.
func TestRenderBlockForIsWhatTheBlockLinksTo(t *testing.T) {
	reset()
	got := RenderBlockFor(homePage)
	uassert.True(t, strings.Contains(got, "(/r/moul/reactions/v0$help&func=React&"),
		"the txlink targets this realm")
	uassert.True(t, strings.Contains(got, "page=gno.land%2Fr%2Fmoul%2Fhome"),
		"and carries the host page as the parameter")
	uassert.False(t, strings.Contains(got, "/r/moul/home$help"),
		"never the host realm, which has no React to call")
}

// TestRenderBlockKeysOnTheCaller is the borrowed-read rule this realm's whole
// ergonomics rest on: RenderBlock has no cur realm parameter, so gno opens no
// frame for it and unsafe.CurrentRealm() reports whoever called.
//
// In-package there is no other realm to call from, so what this pins is the
// half that can be pinned here: RenderBlock agrees with RenderBlockFor when
// the caller IS this realm. The cross-realm half is measured in AGENTS.md
// (2026-09-22) and is the same mechanism r/moul/config's TopBlock uses.
func TestRenderBlockKeysOnTheCaller(t *testing.T) {
	reset()
	uassert.Equal(t, RenderBlockFor(realmPath), RenderBlock())
	uassert.NotEqual(t, RenderBlockFor(homePage), RenderBlock(),
		"and a different page is a different block")
}

func TestRenderPageView(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyUp)

	got := Render(homePage)
	uassert.True(t, strings.HasPrefix(got, "# gno\\.land/r/moul/home\n"),
		"the heading is the page key, escaped: ui.Inline backslashes the dot")
	uassert.True(t, strings.Contains(got, "Last reaction: \U0001F44D by "))
	uassert.True(t, strings.Contains(got, "Remove my reaction"))
	uassert.True(t, strings.Contains(got, "[The board](/r/moul/reactions/v0)"))
}

func TestRenderRejectsAPathThatIsNotAPageKey(t *testing.T) {
	reset()
	got := Render("[click](http://e.vil)")
	uassert.True(t, strings.HasPrefix(got, "# Not a page\n"))
	uassert.False(t, strings.Contains(got, "](http://e.vil)"),
		"a render path is escaped before it is shown back")
}

// TestRenderHomeShowsTheBoard uses uassert rather than an Example because the
// page contains consecutive blank lines, which gno collapses inside an
// // Output: block.
func TestRenderHomeShowsTheBoard(cur realm, t *testing.T) {
	reset()
	uassert.True(t, strings.Contains(Render(""), "*No page has been reacted to yet.*"))

	testing.SetRealm(testing.NewUserRealm(alice))
	React(cross(cur), homePage, rx.KeyParty)

	got := Render("")
	uassert.True(t, strings.Contains(got,
		"| [gno\\.land/r/moul/home](/r/moul/reactions/v0:gno.land/r/moul/home) | 1 |"),
		"the cell text is escaped, the URL is not: they are different contexts")
	uassert.True(t, strings.Contains(got, "import \"gno.land/r/moul/reactions/v0\""),
		"the homepage is the getting-started doc, and the snippet is copy-pasteable")
	for _, k := range rx.Keys() {
		uassert.True(t, strings.Contains(got, "| `"+k+"` | "+rx.Emoji(k)+" |"), k)
	}
}

// TestBoardIndexIsCapped: the number of pages is unbounded, the index is not.
func TestBoardIndexIsCapped(cur realm, t *testing.T) {
	reset()
	for i := 0; i < maxListed+3; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		// Zero-padded, because avl keys sort as strings and ufmt has no width
		// flags: "p9" would otherwise sort between "p10" and "p11".
		n := strconv.Itoa(i)
		if len(n) < 2 {
			n = "0" + n
		}
		React(cross(cur), "gno.land/r/spam/p"+n, rx.KeyUp)
	}
	uassert.Equal(t, maxListed+3, Pages())

	got := Render("")
	uassert.Equal(t, maxListed, strings.Count(got, "(/r/moul/reactions/v0:gno.land/r/spam/"))
	uassert.True(t, strings.Contains(got, "28 pages in total, 25 shown."))
}

package reactions

import (
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	rx "gno.land/p/moul/reactions/v0"
)

// maxListed caps the board index. The number of pages is unbounded (anyone can
// react to any key), and a Render that grows with it would eventually be too
// expensive to serve. The cap is on the INDEX only: every page keeps its own
// view at /r/moul/reactions/v0:<page>, whether or not it is listed here.
const maxListed = 25

// Render serves two views:
//
//	""       the getting-started page: how to embed the block, plus the board
//	"<page>" one page's tally, where <page> is a package path
//
// The page view's path is the key itself, so the link under any embedded block
// is just this realm's path, a colon, and the page. That is why a page key may
// contain a colon of its own: "gno.land/r/you/blog:hello" reads back whole.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if !rx.ValidPage(path) {
		return "# Not a page\n\n" + ui.Inline(path) + " is not a page key: a key is a " +
			"package path, lowercase ASCII, at most " + strconv.Itoa(rx.MaxPageLen) +
			" bytes.\n\n[Back to the board](" + selfURL() + ")\n"
	}
	return renderPage(path)
}

// selfURL is this realm's own gnoweb path, derived from realmPath the same way
// every link in the block is, so there is one rule and not two. A function and
// not a package-level var: a package-level var in a realm is realm STATE,
// persisted and re-read on every call, which is a strange thing for a string
// the compiler could have folded.
func selfURL() string { return rx.RealmURL(realmPath) }

func renderHome() string {
	var b strings.Builder

	b.WriteString("# Reactions\n\n")
	b.WriteString("A reaction block any realm can embed. One line in your `Render`, no state ")
	b.WriteString("on your side, and readers get one-click reactions keyed on the page they ")
	b.WriteString("are looking at.\n\n")
	b.WriteString("It is not a comment system, on purpose. There is no text field anywhere, ")
	b.WriteString("which is what lets it run with no moderation: a closed palette, one ")
	b.WriteString("reaction per address per page, changeable and removable.\n\n")

	b.WriteString("## It looks like this\n\n")
	b.WriteString(blockFor(realmPath))
	b.WriteString("\nThat block is live and it is this realm's own page. Click one.\n\n")

	b.WriteString("## Add it to your realm\n\n")
	b.WriteString("```go\n")
	b.WriteString("import \"" + realmPath + "\"\n\n")
	b.WriteString("func Render(path string) string {\n")
	b.WriteString("\treturn body + reactions.RenderBlock()\n")
	b.WriteString("}\n")
	b.WriteString("```\n\n")
	b.WriteString("That is the whole integration. `RenderBlock` takes no argument because it ")
	b.WriteString("does not need one: a plain read exported by one realm and called by ")
	b.WriteString("another opens no realm frame, so it sees YOUR path and uses it as the ")
	b.WriteString("page key. Nothing to register, nothing to configure.\n\n")
	b.WriteString("For one block per article rather than one per realm, name the page ")
	b.WriteString("yourself with the path you already serve:\n\n")
	b.WriteString("```go\n")
	b.WriteString("return body + reactions.RenderBlockFor(\"gno.land/r/you/blog:\" + path)\n")
	b.WriteString("```\n\n")
	b.WriteString("Reactions are recorded here, not in your realm, so redeploying yours ")
	b.WriteString("never loses them.\n\n")

	b.WriteString("## The palette\n\n")
	t := ui.NewTable("key", "")
	for _, k := range rx.Keys() {
		t.Row("`"+k+"`", rx.Emoji(k))
	}
	b.WriteString(t.String())
	b.WriteString("\nSix, and the set is closed. `React` aborts on anything else, which is ")
	b.WriteString("the entire moderation policy.\n\n")

	b.WriteString("## The board\n\n")
	b.WriteString(renderBoard())

	return b.String()
}

// renderBoard lists pages in key order, not by activity. Key order is the order
// the tree already walks, so the listing is stable between identical calls;
// ranking would need a second index maintained on every write, which is a lot
// of machinery for a table nobody navigates by.
func renderBoard() string {
	n := board.Pages()
	if n == 0 {
		return ui.Empty("No page has been reacted to yet.")
	}

	t := ui.NewTable("page", "reactions", "last")
	board.Each(func(page string, p *rx.Page) bool {
		key, who, _ := p.Last()
		last := "-"
		if key != "" {
			last = rx.Emoji(key) + " " + ui.Addr(who)
		}
		t.Row(
			"["+ui.Cell(page)+"]("+rx.PageURL(realmPath, page)+")",
			strconv.Itoa(p.Total()),
			last,
		)
		return t.Len() >= maxListed
	})

	out := t.String()
	if n > maxListed {
		out += "\n" + strconv.Itoa(n) + " pages in total, " + strconv.Itoa(maxListed) +
			" shown. Every page has its own view at `" + selfURL() + ":<page>`.\n"
	}
	return out
}

func renderPage(page string) string {
	p := board.Page(page)

	var b strings.Builder
	b.WriteString("# " + ui.Inline(page) + "\n\n")
	b.WriteString(blockFor(page))
	b.WriteString("\n")

	if p.Total() == 0 {
		b.WriteString(ui.Empty("Nobody is reacting to this page right now."))
	} else {
		t := ui.NewTable("", "reaction", "addresses")
		for _, k := range rx.Keys() {
			if c := p.Count(k); c > 0 {
				t.Row(rx.Emoji(k), "`"+k+"`", strconv.Itoa(c))
			}
		}
		b.WriteString(t.String())
	}

	if key, who, height := p.Last(); key != "" {
		b.WriteString("\nLast reaction: " + rx.Emoji(key) + " by " + ui.Addr(who) +
			" at height " + strconv.FormatInt(height, 10) + ".\n")
	}

	b.WriteString("\n" + ui.ActionIn(realmPath, "Remove my reaction", "Unreact", "page", page))
	b.WriteString(" · [The board](" + selfURL() + ")\n")
	return b.String()
}

// Package home is the realm behind https://gno.land/u/moul.
//
// gnoweb builds a user profile page by calling Render("") on the realm at the
// exact path /r/<username>/home (gno.land/pkg/gnoweb/handler_http.go,
// GetUserView) and embedding the result as the profile body. There is no
// version resolution in that lookup, which is why this realm (alone in this
// repo) carries no /vN suffix: the bare path IS the interface with gnoweb,
// and gno.land/r/moul/home/v0 would never be found.
//
// # Slots
//
// The page is not hard-coded. It is assembled from SLOTS: named markdown
// fragments in an avl tree, each written by its own Set call, so updating one
// paragraph is one small transaction instead of a redeploy.
//
// The layout is itself a slot ("layout"), so the shape of the page (headings,
// order, what appears at all) changes without touching the code.
// p/moul/dynreplacer fills every :slug: placeholder found in the layout, lazily:
// a slot whose placeholder is absent from the layout costs nothing to render.
//
// Substitution is SINGLE-PASS and non-recursive. A placeholder inside a slot
// body is left alone, so no slot can expand into another and no cycle exists.
// Two registered placeholders can never be prefixes of one another either
// (every one is :slug: and a slug may not contain ':'), so the result does not
// depend on registration order.
//
// A placeholder with no matching slot survives into the output verbatim. That
// is deliberate: a missing section should be visible, not silently blank.
//
// # Versioning
//
// gnomod.toml declares private = true, which lets the creator re-add the
// package at this path. That redeploy re-runs init() and RESETS everything
// here, so the markdown under content/ is the source of truth and
// tools/gnohome pushes the slots back afterwards. The intended path is that this
// never happens: slots cover content, and the layout slot covers presentation.
package home

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// admin is the only address allowed to write. Deliberately a constant and not
// transferable ownership: this realm is one person's profile page, and the
// same address is the only one the chain lets redeploy it.
const admin = address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")

// layoutSlug names the slot used as the page template.
const layoutSlug = "layout"

// realmPath is this realm's own path. Written out rather than read from
// unsafe.CurrentRealm() because it is also the interface with gnoweb (see the
// package doc): the constant is the thing that must not drift, so it is stated
// once and every other use points here.
const realmPath = "gno.land/r/moul/home"

// maxSlugLen bounds a slug so an index row stays readable and a key stays cheap.
const maxSlugLen = 64

var (
	slots = avl.NewTree() // slug -> *slot
	rev   int             // total number of writes, bumped by every mutation
)

type slot struct {
	body    string
	rev     int   // rev at the time of the last write to this slot
	updated int64 // block height of the last write
}

// reservedSlugs are placeholder names computed at render time from chain state.
// A slot may not take one, because it would shadow the computed value and make
// the page depend on callback registration order.
//
// The scan.* half comes from scan.gno's scanPlaceholders and the :reactions:
// one from reactions.gno, so adding a placeholder in either file reserves it
// here and cannot be forgotten.
var reservedSlugs = append(
	append(
		[]string{"chainid", "height", "owner", "realm", "rev", "slots"},
		scanPlaceholders...,
	),
	reactionsPlaceholders...,
)

func assertAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("restricted to admin")
	}
}

// validSlug reports whether slug is a legal slot name: 1..maxSlugLen bytes of
// [a-z0-9._-]. The character set excludes ':' so a slug can never break out of
// its own :slug: placeholder, and excludes uppercase so a slot has one name.
func validSlug(slug string) bool {
	if len(slug) == 0 || len(slug) > maxSlugLen {
		return false
	}
	for i := 0; i < len(slug); i++ {
		c := slug[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '-', c == '_', c == '.':
		default:
			return false
		}
	}
	return true
}

func assertWritableSlug(slug string) {
	if !validSlug(slug) {
		panic("invalid slug: want 1-" + strconv.Itoa(maxSlugLen) + " bytes of [a-z0-9._-], got " + strconv.Quote(slug))
	}
	for _, r := range reservedSlugs {
		if slug == r {
			panic("reserved slug: " + slug + " is computed at render time")
		}
	}
}

// Set creates or replaces the slot named slug. This is the ordinary update: one
// slot, one transaction. Passing the empty body keeps the slot but empties it;
// use Delete to remove it.
func Set(cur realm, slug, body string) {
	assertAdmin(cur)
	assertWritableSlug(slug)
	rev++
	slots.Set(slug, &slot{body: body, rev: rev, updated: chainHeight()})
}

// Append adds to the end of a slot, creating it when absent. It exists for
// content too large to fit in one transaction: Set the first chunk, Append the
// rest. Ordinary updates should use Set, which is idempotent.
func Append(cur realm, slug, body string) {
	assertAdmin(cur)
	assertWritableSlug(slug)
	rev++
	prev := ""
	if v := slots.Get(slug); v != nil {
		prev = v.(*slot).body
	}
	slots.Set(slug, &slot{body: prev + body, rev: rev, updated: chainHeight()})
}

// Delete removes a slot. Deleting the layout slot restores the built-in
// default layout.
func Delete(cur realm, slug string) {
	assertAdmin(cur)
	if _, removed := slots.Remove(slug); !removed {
		panic("no such slot: " + slug)
	}
	rev++
}

// Get returns a slot body, or "" when the slot does not exist.
func Get(slug string) string {
	v := slots.Get(slug)
	if v == nil {
		return ""
	}
	return v.(*slot).body
}

// Revision returns the total number of writes this realm has accepted. It
// changes on every mutation, so a client can cheaply tell "nothing moved".
func Revision() int {
	return rev
}

// Manifest returns one tab-separated line per slot:
//
//	<slug>\t<rev>\t<len>\t<sha256 of body, hex>
//
// It is the diff surface tools/gnohome queries with vm/qeval: one read tells it
// exactly which local file is out of date, without downloading any body.
func Manifest() string {
	var b strings.Builder
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*slot)
		sum := sha256.Sum256([]byte(s.body))
		b.WriteString(key)
		b.WriteString("\t")
		b.WriteString(strconv.Itoa(s.rev))
		b.WriteString("\t")
		b.WriteString(strconv.Itoa(len(s.body)))
		b.WriteString("\t")
		b.WriteString(hex.EncodeToString(sum[:]))
		b.WriteString("\n")
		return false
	})
	return b.String()
}

